typedef struct {
    uint8_t *data;
    size_t length;
    size_t capacity;
} secure_buffer_t;

typedef struct {
    char algorithm[16];
    char key_id[64];
} token_header_t;

typedef struct {
    char issuer[128];
    uint64_t expiry;
    uint64_t issued_at;
    char subject[256];
} token_claims_t;

typedef struct {
    unsigned char key_material[512];
    size_t key_length;
    char key_type[16]; // "hmac" or "rsa"
    char key_id[64];
} key_entry_t;

// Key store with pre-registered keys
static key_entry_t key_store[8];
static int key_store_count = 0;

int register_key(const char *kid, const char *type, const unsigned char *material, size_t mat_len) {
    if (key_store_count >= 8) return -1;
    if (mat_len > 512) return -1;
    key_entry_t *entry = &key_store[key_store_count];
    strncpy(entry->key_id, kid, 63);
    entry->key_id[63] = '\0';
    strncpy(entry->key_type, type, 15);
    entry->key_type[15] = '\0';
    memcpy(entry->key_material, material, mat_len);
    entry->key_length = mat_len;
    key_store_count++;
    return 0;
}

key_entry_t* lookup_key(const char *kid) {
    for (int i = 0; i < key_store_count; i++) {
        if (strcmp(key_store[i].key_id, kid) == 0) {
            return &key_store[i];
        }
    }
    return NULL;
}

// Compute decoded length from base64url input
// Returns the number of bytes the decoded output will occupy
static size_t b64url_decoded_length(const char *input, size_t input_len) {
    if (input_len == 0) return 0;

    // Count padding characters (base64url may omit padding)
    size_t padding = 0;
    if (input_len >= 1 && input[input_len - 1] == '=') padding++;
    if (input_len >= 2 && input[input_len - 2] == '=') padding++;

    // Standard formula: (input_len * 3) / 4 - padding
    // For base64url without padding, we adjust based on remainder
    size_t adjusted_len = input_len;
    switch (input_len % 4) {
        case 0: break;
        case 2: adjusted_len += 2; break; // would have 2 padding chars
        case 3: adjusted_len += 1; break; // would have 1 padding char
        case 1: return 0; // invalid
    }

    return (adjusted_len * 3) / 4 - padding;
}

// Decode base64url to binary
static int b64url_decode(const char *input, size_t input_len, uint8_t *output, size_t output_capacity, size_t *output_len) {
    size_t expected = b64url_decoded_length(input, input_len);
    if (expected == 0 && input_len > 0) return -1;

    // Bounds check: ensure output buffer is large enough
    if (expected > output_capacity) return -1;

    size_t i = 0, j = 0;
    uint32_t accum = 0;
    int bits = 0;

    for (i = 0; i < input_len; i++) {
        if (input[i] == '=' || input[i] == '\0') break;
        int8_t val = b64_decode_table[(unsigned char)input[i]];
        if (val < 0) return -1;
        accum = (accum << 6) | (uint32_t)val;
        bits += 6;
        if (bits >= 8) {
            bits -= 8;
            if (j >= output_capacity) return -1; // Additional safety check
            output[j++] = (uint8_t)((accum >> bits) & 0xFF);
        }
    }

    *output_len = j;
    return 0;
}

// Parse a minimal JSON-like header: {"alg":"...","kid":"..."}
static int parse_header(const uint8_t *data, size_t len, token_header_t *header) {
    memset(header, 0, sizeof(*header));

    const char *alg_start = NULL;
    const char *kid_start = NULL;
    const char *s = (const char *)data;

    for (size_t i = 0; i + 5 < len; i++) {
        if (memcmp(s + i, "\"alg\"", 5) == 0) {
            // Find the value
            size_t j = i + 5;
            while (j < len && s[j] != '"') j++;
            if (j < len) {
                j++; // skip opening quote
                alg_start = s + j;
                size_t k = j;
                while (k < len && s[k] != '"') k++;
                size_t alg_len = k - j;
                if (alg_len < sizeof(header->algorithm)) {
                    memcpy(header->algorithm, alg_start, alg_len);
                    header->algorithm[alg_len] = '\0';
                }
            }
        }
        if (memcmp(s + i, "\"kid\"", 5) == 0) {
            size_t j = i + 5;
            while (j < len && s[j] != '"') j++;
            if (j < len) {
                j++;
                kid_start = s + j;
                size_t k = j;
                while (k < len && s[k] != '"') k++;
                size_t kid_len = k - j;
                if (kid_len < sizeof(header->key_id)) {
                    memcpy(header->key_id, kid_start, kid_len);
                    header->key_id[kid_len] = '\0';
                }
            }
        }
    }

    return (header->algorithm[0] != '\0') ? 0 : -1;
}

// HMAC-SHA256 simplified (for demonstration - uses XOR-based MAC)
// In production this would use OpenSSL HMAC
static void compute_hmac(const uint8_t *key, size_t key_len,
                         const uint8_t *msg, size_t msg_len,
                         uint8_t *mac_out, size_t *mac_len) {
    // Simplified keyed hash for demonstration
    uint8_t padded_key[64];
    memset(padded_key, 0, 64);
    if (key_len <= 64) {
        memcpy(padded_key, key, key_len);
    } else {
        // Simple hash reduction
        for (size_t i = 0; i < key_len; i++) {
            padded_key[i % 64] ^= key[i];
        }
    }

    uint8_t inner[64];
    uint8_t outer[64];
    for (int i = 0; i < 64; i++) {
        inner[i] = padded_key[i] ^ 0x36;
        outer[i] = padded_key[i] ^ 0x5c;
    }

    // Simple hash: XOR fold the message with inner key
    uint8_t hash[32];
    memset(hash, 0, 32);
    for (size_t i = 0; i < 64; i++) hash[i % 32] ^= inner[i];
    for (size_t i = 0; i < msg_len; i++) hash[i % 32] ^= msg[i];

    // Outer pass
    uint8_t result[32];
    memset(result, 0, 32);
    for (size_t i = 0; i < 64; i++) result[i % 32] ^= outer[i];
    for (size_t i = 0; i < 32; i++) result[i] ^= hash[i];

    memcpy(mac_out, result, 32);
    *mac_len = 32;
}

// Constant-time comparison
static int secure_compare(const uint8_t *a, const uint8_t *b, size_t len) {
    volatile uint8_t diff = 0;
    for (size_t i = 0; i < len; i++) {
        diff |= a[i] ^ b[i];
    }
    return diff == 0;
}

// Signature verification buffer allocation
// This function computes the required buffer size for the decoded signature
static secure_buffer_t* allocate_signature_buffer(const char *sig_b64, size_t sig_b64_len) {
    // Calculate the expected decoded signature length
    size_t decoded_len = b64url_decoded_length(sig_b64, sig_b64_len);

    // Guard against zero-length allocation
    if (decoded_len == 0) return NULL;

    // Add safety margin to prevent any edge-case underallocation
    size_t alloc_size = decoded_len + 4;

    // Overflow check
    if (alloc_size < decoded_len) return NULL;

    // Allocate buffer with safety margin
    secure_buffer_t *buf = (secure_buffer_t *)malloc(sizeof(secure_buffer_t));
    if (!buf) return NULL;

    buf->capacity = alloc_size;
    buf->length = 0;
    buf->data = (uint8_t *)malloc(alloc_size);
    if (!buf->data) {
        free(buf);
        return NULL;
    }
    memset(buf->data, 0, alloc_size);

    return buf;
}

static void free_secure_buffer(secure_buffer_t *buf) {
    if (buf) {
        if (buf->data) {
            memset(buf->data, 0, buf->capacity);
            free(buf->data);
        }
        free(buf);
    }
}

// Verify a token's signature
// Token format: <base64url_header>.<base64url_payload>.<base64url_signature>
int verify_token(const char *token, size_t token_len) {
    // Find the dots
    const char *first_dot = NULL;
    const char *second_dot = NULL;

    for (size_t i = 0; i < token_len; i++) {
        if (token[i] == '.') {
            if (!first_dot) first_dot = token + i;
            else if (!second_dot) second_dot = token + i;
        }
    }

    if (!first_dot || !second_dot) return -1;

    size_t header_b64_len = first_dot - token;
    size_t payload_b64_len = second_dot - first_dot - 1;
    size_t sig_b64_len = token_len - (second_dot - token) - 1;

    // Reject empty segments
    if (header_b64_len == 0 || sig_b64_len == 0) return -1;

    // Decode header
    uint8_t header_buf[512];
    size_t header_len = 0;
    if (b64url_decode(token, header_b64_len, header_buf, sizeof(header_buf), &header_len) != 0) {
        return -1;
    }

    // Parse header
    token_header_t header;
    if (parse_header(header_buf, header_len, &header) != 0) {
        return -1;
    }

    // Validate algorithm - strict allowlist
    if (strcmp(header.algorithm, "HS256") != 0) {
        return -1; // Only support HS256 for now
    }

    // Look up key
    key_entry_t *key = lookup_key(header.key_id);
    if (!key) return -1;

    // Verify key type matches algorithm
    if (strcmp(key->key_type, "hmac") != 0) {
        return -1;
    }

    // Allocate signature buffer and decode signature
    const char *sig_start = second_dot + 1;
    secure_buffer_t *sig_buf = allocate_signature_buffer(sig_start, sig_b64_len);
    if (!sig_buf) return -1;

    // Decode the signature into the allocated buffer
    size_t actual_decoded = 0;
    if (b64url_decode(sig_start, sig_b64_len, sig_buf->data, sig_buf->capacity, &actual_decoded) != 0) {
        free_secure_buffer(sig_buf);
        return -1;
    }
    sig_buf->length = actual_decoded;

    // Compute expected HMAC over header.payload
    size_t signing_input_len = second_dot - token;
    uint8_t expected_mac[32];
    size_t mac_len = 0;
    compute_hmac(key->key_material, key->key_length,
                 (const uint8_t *)token, signing_input_len,
                 expected_mac, &mac_len);

    // Verify signature length matches expected MAC length
    if (sig_buf->length != mac_len) {
        free_secure_buffer(sig_buf);
        return -1;
    }

    // Constant-time comparison
    int valid = secure_compare(sig_buf->data, expected_mac, mac_len);

    free_secure_buffer(sig_buf);
    return valid ? 0 : -1;
}

// Process incoming authentication request
// This handles the token extraction and validation pipeline
int process_auth_request(const char *auth_header) {
    if (!auth_header) return -1;

    // Expect "Bearer <token>"
    if (strncmp(auth_header, "Bearer ", 7) != 0) return -1;

    const char *token = auth_header + 7;
    size_t token_len = strlen(token);

    // Sanity check on token length
    if (token_len < 16 || token_len > 8192) return -1;

    return verify_token(token, token_len);
}

// Batch verification: verify multiple tokens from a request
// Used in microservice-to-microservice auth where multiple claims are chained
int verify_token_chain(const char **tokens, int count) {
    if (count <= 0 || count > 16) return -1;

    for (int i = 0; i < count; i++) {
        if (!tokens[i]) return -1;
        size_t len = strlen(tokens[i]);
        if (verify_token(tokens[i], len) != 0) {
            return -1;
        }
    }
    return 0;
}

